 */
_Check_return_
BOOL
PropertyStorage_GetValueByKey(
    _In_z_                      const wchar_t*  PwszKey,
    _Out_z_cap_(*PpunValueSize) wchar_t*        PwszValue,
    _Inout_                     unsigned int*   PpunValueSize)
{
    BOOL fReturnValue = FALSE;

    do
    {
        IfxPropertyElement* pElement = NULL;

        // Check parameters
        if (NULL == PwszKey ||
                NULL == PwszValue ||
                NULL == PpunValueSize ||
                0 == *PpunValueSize)
            break;

        // Get element to be read from, if existing
        pElement = PropertyStorage_GetElementByKey(PwszKey);
        if (NULL == pElement)
            break;

        // Get value
        if (RC_SUCCESS == Platform_StringCopy(PwszValue, PpunValueSize, pElement->wszValue))
            fReturnValue = TRUE;
    }
    WHILE_FALSE_END;

    if (FALSE == fReturnValue)
    {
        // Reset out parameters
        if (NULL != PwszValue)
            PwszValue[0] = L'\0';
        if (NULL != PpunValueSize)
            *PpunValueSize = 0;
    }

    return fReturnValue;
}

/**
 *  @brief      Find key by partial or full name with optional key name to start search from
 *  @details
 *
 *  @param      PwszSearch      Search string for a key name as null-terminated wide char array.
 *  @param      PwszStartKey    Optional wide char array containing a start key name or NULL.
 *  @param      PwszKey         Pointer to a wide char array containing the first found key name.
 *  @param      PpunKeySize     In: the capacity of the wide char array in elements (incl. termination zero)\n
 *                              Out: the length of the string copied to (without termination zero)
 *
 *  @retval     TRUE        If the operation was successful.
 *  @retval     FALSE       If the key could not be found, e.g. because no (further) element with the given key name exists.
 */
_Check_return_
BOOL
PropertyStorage_FindKey(
    _In_z_                      const wchar_t*  PwszSearch,
    _In_opt_z_                  const wchar_t*  PwszStartKey,
    _Out_z_cap_(*PpunKeySize)   wchar_t*        PwszKey,
    _Inout_                     unsigned int*   PpunKeySize)
{
    BOOL fReturnValue = FALSE;

    do
    {
        IfxPropertyElement* pElement = NULL;

        // Check parameters
        if (NULL == PwszSearch ||
                NULL == PwszKey ||
                NULL == PpunKeySize ||
                0 == *PpunKeySize)
            break;

        if (NULL == PwszStartKey)
            pElement = s_pvHead;
        else
        {
            // Get start element if existing
            pElement = PropertyStorage_GetElementByKey(PwszStartKey);
            if (NULL == pElement)
                break;

            pElement = pElement->pvNextElement;
        }

        while (NULL != pElement)
        {
            // Check if current element contains the given key
            wchar_t* pwszKey = NULL;
            if (0 == Platform_FindString(PwszSearch, pElement->wszKey, &pwszKey) && pwszKey)
            {
                // Copy key value
                if (RC_SUCCESS == Platform_StringCopy(PwszKey, PpunKeySize, pwszKey))
                    fReturnValue = TRUE;

                break;
            }

            // Update iterator
            pElement = pElement->pvNextElement;
        }
    }
    WHILE_FALSE_END;

    if (FALSE == fReturnValue)
    {
        // Reset out parameters
        if (NULL != PwszKey)
            PwszKey[0] = L'\0';
        if (NULL != PpunKeySize)
            *PpunKeySize = 0;
    }

    return fReturnValue;
}

/**
 *  @brief      Get the value of the PropertyElement with the given key casted to a BOOL
 *  @details
 *
 *  @param      PwszKey         Key identifier for the PropertyElement to obtain the value from\n
 *                              null-terminated wide char array
 *  @param      PpfValue        Pointer to a BOOL containing the PropertyElement value.
 *
 *  @retval     TRUE        If the operation was successful.
 *  @retval     FALSE       If the value could not be retrieved, e.g. because no element with the given key has been found.
 */
_Check_return_
BOOL
PropertyStorage_GetBooleanValueByKey(
    _In_z_  const wchar_t*  PwszKey,
    _Out_   BOOL*           PpfValue)
{
    BOOL fReturnValue = FALSE;

    do
    {
        wchar_t wszValue[PROPERTY_STORAGE_MAX_VALUE];
        unsigned int unValueSize = RG_LEN(wszValue);
        IGNORE_RETURN_VALUE(Platform_StringSetZero(wszValue, RG_LEN(wszValue)));

        // Check parameters
        if (NULL == PwszKey ||
                NULL == PpfValue)
            break;

        *PpfValue = FALSE;

        if (FALSE == PropertyStorage_GetValueByKey(PwszKey, wszValue, &unValueSize))
            break;

        // Increment size by one due to null-termination
        if (PROPERTY_STORAGE_MAX_VALUE > unValueSize)
            unValueSize++;

        // Convert value to BOOL, if possible
        if (0 == Platform_StringCompare(L"TRUE", wszValue, unValueSize, TRUE))
        {
            *PpfValue = TRUE;
            fReturnValue = TRUE;
        }
        else if (0 == Platform_StringCompare(L"FALSE", wszValue, unValueSize, TRUE))
        {
            *PpfValue = FALSE;
            fReturnValue = TRUE;
        }
    }
    WHILE_FALSE_END;

    return fReturnValue;
}

/**
 *  @brief      Get the value of the PropertyElement with the given key casted to an unsigned integer
 *  @details
 *
 *  @param      PwszKey         Key identifier for the PropertyElement to obtain the value from\n
 *                              null-terminated wide char array
 *  @param      PpunValue       Pointer to an unsigned integer containing the PropertyElement value.
 *
 *  @retval     TRUE        If the operation was successful.
 *  @retval     FALSE       If the value could not be retrieved, e.g. because no element with the given key has been found.
 */
_Check_return_
BOOL
PropertyStorage_GetUIntegerValueByKey(
    _In_z_  const wchar_t*      PwszKey,
    _Out_   unsigned int*       PpunValue)
{
    BOOL fReturnValue = FALSE;

    do
    {
        wchar_t wszValue[PROPERTY_STORAGE_MAX_VALUE];
        unsigned int unValueSize = RG_LEN(wszValue);
        int nIndex = -1;
        IGNORE_RETURN_VALUE(Platform_StringSetZero(wszValue, RG_LEN(wszValue)));

        // Check parameters
        if (NULL == PwszKey ||
                NULL == PpunValue)
            break;

        if (FALSE == PropertyStorage_GetValueByKey(PwszKey, wszValue, &unValueSize))
            break;

        // Increment size by one due to null-termination
        if (PROPERTY_STORAGE_MAX_VALUE > unValueSize)
            unValueSize++;

        // Convert String to Integer
        if (RC_SUCCESS == Utility_StringContainsWChar(wszValue, unValueSize, L'x', &nIndex))
        {
            if (nIndex == -1)
            {
                // Convert as decimal value
                if (RC_SUCCESS == Utility_StringParseUInteger(wszValue, unValueSize, PpunValue))
                    fReturnValue = TRUE;
            }
            else
            {
                // Convert as hex value
                if (RC_SUCCESS == Utility_UIntegerParseHexString(wszValue, PpunValue))
                    fReturnValue = TRUE;
            }
        }
    }
    WHILE_FALSE_END;

    if (FALSE == fReturnValue)
        // Reset out parameters
        if (NULL != PpunValue)
            *PpunValue = 0;

    return fReturnValue;
}

